 @Override public void onCreate(Bundle saved){super.onCreate(saved);data=NoirApp.data;store=NoirApp.downloads;ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setFitsSystemWindows(true);scroll.setBackgroundColor(MainActivity.BLACK);body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);int pad=dp(this,22);body.setPadding(pad,pad,pad,pad);scroll.addView(body);setContentView(scroll);body.addView(button(this,"‹ Back",this::finish));body.addView(label(this,"Downloads",30));readyBody=new LinearLayout(this);readyBody.setOrientation(LinearLayout.VERTICAL);body.addView(readyBody);if(data.paired())add("Downloads on PC",PcDownloadsActivity.class);add("Offline on phone",DownloadsActivity.class);add("Discover something new",DiscoverActivity.class);add("Phone download settings",PhoneDownloadSettingsActivity.class);renderReady();Loc.apply(this);}
 void add(String title,Class<?> activity){body.addView(button(this,title,()->startActivity(new Intent(this,activity))));}
 void refresh(){if(loading||data!=NoirApp.data)return;loading=true;data.images.execute(()->{long count=PhoneReadyJob.used(store);PhoneReady p=PhoneReadyJob.policy(data);p.planned(PhoneReadyJob.plan(data));ui.post(()->{loading=false;if(!isFinishing()&&data==NoirApp.data){used=count;renderReady();}});});}
 void toggle(String key,boolean value){PhoneReady p=PhoneReadyJob.policy(data);p.setting(key,value);if(key.equals("pickup")&&!value)store.pausePickupExcept(Collections.emptySet());if(key.equals("paused")&&value||key.equals("enabled")&&!value)for(JSONObject j:DataStore.objects(store.jobs()))if(j.optBoolean("readyManaged")&&!j.optString("status").equals("complete")&&(key.equals("paused")||!j.optBoolean("readyPickup")))store.pause(j.optString("id"));PhoneReadyJob.refill(this);PhonePickupJob.kick(this);renderReady();}
 void switchRow(String title,String key,boolean value){Switch s=new Switch(this);s.setText(Loc.t(title));s.setTextColor(MainActivity.WHITE);s.setTextSize(15);s.setPadding(0,dp(this,8),0,dp(this,8));s.setMinHeight(dp(this,52));s.setChecked(value);s.setOnCheckedChangeListener((v,on)->toggle(key,on));readyBody.addView(s);}
 static boolean pickupId(PhoneReady p,String id){for(JSONObject i:DataStore.objects(p.snapshot().optJSONArray("pickupQueue")))if(id.equals(i.optString("id")))return true;return false;}
 static String pickupState(Activity a,DataStore data,DownloadStore store,PhoneReady p){String block=p.pickupPolicy(data.paired());if(!block.isEmpty())return Loc.t(block);block=PhonePickupJob.wifi(a);if(!block.isEmpty())return Loc.t(block);int complete=0,copying=0,waiting=0;for(JSONObject j:DataStore.objects(store.jobs()))if(j.optBoolean("readyManaged")&&j.optBoolean("readyPickup")){if(j.optString("status").equals("complete"))complete++;else if(j.optString("id").equals(store.activeId))copying++;else if(!j.optBoolean("pickupCancelled"))waiting++;}if(copying>0)return Loc.f("%d copied · %d copying",complete,copying);if(!p.pickupReason().isEmpty())return Loc.t(p.pickupReason());if(complete>0||waiting>0)return Loc.f("%d copied · %d waiting",complete,waiting);return Loc.t("Waiting for your PC");}
