 void renderPickup(PhoneReady p){Switch s=new Switch(this);s.setText(Loc.t("Bring unfinished PC episodes"));s.setTextColor(MainActivity.WHITE);s.setTextSize(15);s.setPadding(0,dp(this,8),0,dp(this,8));s.setMinHeight(dp(this,52));s.setChecked(p.pickupEnabled());s.setEnabled(data.paired());s.setOnCheckedChangeListener((v,on)->toggle("pickup",on));readyBody.addView(s);readyBody.addView(label(this,"When you're home on Wi-Fi and your PC is on, the episodes you started on the PC are copied here so you can finish them anywhere.",12));readyBody.addView(label(this,data.paired()?pickupState(this,data,store,p):"Pair with your PC to bring unfinished episodes",14));List<JSONObject> jobs=new ArrayList<>();for(JSONObject j:DataStore.objects(store.jobs()))if(j.optBoolean("readyManaged")&&j.optBoolean("readyPickup"))jobs.add(j);if(jobs.isEmpty())return;readyBody.addView(label(this,"PC pickup copies",18));for(int n=0;n<Math.min(20,jobs.size());n++){JSONObject j=jobs.get(n);String id=j.optString("id"),status=j.optString("status").equals("readyQueued")?Loc.t("Waiting to copy from your PC"):Loc.t(j.optString("status"));readyBody.addView(button(this,j.optString("title")+"\n"+status+" · "+size(j.optLong("bytes"))+" / "+size(j.optLong("total")),()->startActivity(new Intent(this,j.optString("status").equals("complete")?PlayerActivity.class:DownloadsActivity.class).putExtra("id",id))));String why=p.lastReason(id);if(!why.isEmpty())readyBody.addView(label(this,why,12));readyBody.addView(button(this,"Keep",()->{p.protect(id,true);store.pinReady(id);renderReady();}));}}
 void renderReady(){PhoneReady p=PhoneReadyJob.policy(data);readyBody.removeAllViews();readyBody.setPadding(0,dp(this,10),0,dp(this,22));readyBody.addView(label(this,"Keep ready",24));switchRow("Keep ready on this phone","enabled",p.enabled());readyBody.addView(label(this,"Overnight · unmetered Wi-Fi · charging · 2 GB kept free",12));switchRow("Pause preparation","paused",p.paused());String block=!p.enabled()?"Keep ready is off":p.paused()?"Preparation paused":!PhoneReadyJob.conditions(this).isEmpty()?PhoneReadyJob.conditions(this):p.reason();if(!block.isEmpty()){TextView reason=label(this,block,14);reason.setTextColor(MainActivity.GOLD);readyBody.addView(reason);}renderPickup(p);readyBody.addView(button(this,Loc.f("Phone budget: %s",size(p.budget())),()->{long[] gb={2,5,10,20};String[] choices=new String[4];for(int n=0;n<4;n++)choices[n]=size(gb[n]*PhoneReady.GB);new AlertDialog.Builder(this).setTitle(Loc.t("Phone budget")).setItems(choices,(d,n)->{p.setting("budget",gb[n]*PhoneReady.GB);renderReady();}).setNegativeButton(Loc.t("Cancel"),null).show();}));ProgressBar bar=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);bar.setMax(1000);bar.setProgress((int)Math.min(1000,1000d*used/p.budget()));bar.setProgressTintList(android.content.res.ColorStateList.valueOf(MainActivity.GOLD));readyBody.addView(bar,new LinearLayout.LayoutParams(-1,dp(this,6)));readyBody.addView(label(this,Loc.f("%s of %s used on this phone",size(used),size(p.budget())),12));switchRow("Remove watched after 7 days","cleanup",p.cleanup());readyBody.addView(label(this,"Only Ready downloads are removed. Unwatched and kept files stay.",12));readyBody.addView(label(this,"Next episodes",18));Map<String,JSONObject> jobs=new HashMap<>();for(JSONObject j:DataStore.objects(store.jobs()))jobs.put(j.optString("id"),j);List<JSONObject> queue=DataStore.objects(p.snapshot().optJSONArray("queue"));if(queue.isEmpty())readyBody.addView(label(this,"Choose Keep ready on a show to prepare its next episodes.",13));for(int n=0;n<Math.min(30,queue.size());n++){JSONObject item=queue.get(n),j=jobs.get(item.optString("id"));String status=j==null?Loc.t("Preparing overnight"):Loc.t(j.optString("status"))+" · "+size(j.optLong("bytes"))+" / "+size(j.optLong("total"));readyBody.addView(button(this,item.optString("title")+" · "+MainActivity.episode(item),()->openKeepReady(this,item.optString("group"))));readyBody.addView(label(this,status,12));String why=p.lastReason(item.optString("id"));if(!why.isEmpty())readyBody.addView(label(this,why,12));if(j!=null&&j.optBoolean("readyManaged"))readyBody.addView(button(this,"Keep",()->{p.protect(item.optString("id"),true);store.pinReady(item.optString("id"));renderReady();}));}readyBody.addView(label(this,"Scheduled removals",18));List<JSONObject> removals=DataStore.objects(p.removals());if(removals.isEmpty())readyBody.addView(label(this,"No removals scheduled",13));for(JSONObject r:removals){String id=r.optString("id");JSONObject j=jobs.get(id);readyBody.addView(label(this,(j==null?Loc.t("Phone copy"):j.optString("title"))+" · "+android.text.format.DateFormat.getDateFormat(this).format(new Date(r.optLong("at"))),14));readyBody.addView(button(this,"Keep",()->{p.protect(id,true);store.pinReady(id);renderReady();}));readyBody.addView(button(this,"Cancel removal",()->{p.protect(id,false);renderReady();}));}readyBody.addView(label(this,"Why log",18));List<JSONObject> why=DataStore.objects(p.snapshot().optJSONArray("why"));for(int n=why.size()-1;n>=Math.max(0,why.size()-12);n--){JSONObject row=why.get(n),j=jobs.get(row.optString("id"));readyBody.addView(label(this,(j==null?"":j.optString("title")+" · ")+Loc.t(row.optString("reason")),12));}}
 static String size(long bytes){return String.format(Locale.getDefault(),"%.1f %s",Math.max(0,bytes)/(double)PhoneReady.GB,Loc.t("GB"));}
